"use client";

/*
 * Behaviour the dialog gets from a Radix-style layer stack: FocusScope, the
 * Escape stack and the helpers around them, based on Radix UI. The
 * DismissableLayer itself lives in lib/dismissable-layer, which tooltips share.
 */

import { noCleanup, useLatest } from "@/lib/dismissable-layer";
import { useCallback, useEffect, useMemo, useSyncExternalStore } from "react";
import type {
  KeyboardEvent as ReactKeyboardEvent,
  Ref,
  RefCallback,
  RefObject,
} from "react";

/* ----------------------------------------------------------------- refs --- */

/** True for `null` and `undefined`, the two values the component tests with `== null`. */
const isNil = <T>(value: T): value is T & (null | undefined) =>
  value === null || value === undefined;

type RefCleanup = (() => void) | undefined;

const setRef = <T>(ref: Ref<T> | undefined, value: T | null): RefCleanup => {
  if (isNil(ref)) {
    return undefined;
  }

  // oxlint-disable-next-line anti-slop/no-runtime-typeof -- A ref is a callback or an object.
  if (typeof ref === "function") {
    const cleanup = ref(value);

    // oxlint-disable-next-line anti-slop/no-runtime-typeof -- A callback ref returns a cleanup function or nothing.
    return typeof cleanup === "function" ? cleanup : undefined;
  }

  // oxlint-disable-next-line react/refs -- This is the merged ref callback: it writes the element into each object ref it was given.
  ref.current = value;

  return undefined;
};

/**
 * Merges refs into one callback ref. A callback ref may return a cleanup
 * function (React 19); the merged ref then returns one that calls each
 * cleanup, and resets the refs that returned none, as React does.
 */
const mergeRefs =
  <T>(...refs: readonly (Ref<T> | undefined)[]): RefCallback<T> =>
  (value: T | null) => {
    const cleanups = refs.map((ref) => setRef(ref, value));

    return () => {
      for (const [index, ref] of refs.entries()) {
        const cleanup = cleanups[index];

        // oxlint-disable-next-line anti-slop/no-runtime-typeof -- The cleanup is a function or nothing.
        if (typeof cleanup === "function") {
          cleanup();
        } else {
          setRef(ref, null);
        }
      }
    };
  };

/** The event type names Radix uses for focus scopes. */
const AUTOFOCUS_ON_MOUNT = "focusScope.autoFocusOnMount";
const AUTOFOCUS_ON_UNMOUNT = "focusScope.autoFocusOnUnmount";

/* ------------------------------------------------------------- tabbable --- */

type FocusableElement = HTMLElement | SVGElement;

/** The focused element, looking through open shadow roots. */
const deepActiveElement = (): Element | null => {
  let active = document.activeElement;

  while (active?.shadowRoot?.activeElement) {
    active = active.shadowRoot.activeElement;
  }

  return active;
};

/** The element hosting the shadow root that holds `node`, if any. */
const shadowHost = (node: Node): Element | null => {
  const root = node.getRootNode();

  return root instanceof ShadowRoot ? root.host : null;
};

/** Whether `node` is inside `container`, crossing shadow roots. */
const containsDeep = (container: Node, node: Node | null): boolean => {
  let current = node;

  while (current) {
    if (container.contains(current)) {
      return true;
    }

    current = shadowHost(current);
  }

  return false;
};

/** Visibility fallback for browsers without `checkVisibility`. */
const isHidden = (node: FocusableElement, upTo: HTMLElement) => {
  if (getComputedStyle(node).visibility === "hidden") {
    return true;
  }

  let current: Element | null = node;

  while (current) {
    if (current === upTo) {
      return false;
    }

    if (getComputedStyle(current).display === "none") {
      return true;
    }

    current =
      current.assignedSlot ?? current.parentElement ?? shadowHost(current);
  }

  return false;
};

/**
 * The tabbable candidates in tree order. The walk skips hidden
 * and inert subtrees, enters open shadow roots (a host that delegates focus
 * is not itself a candidate, and one with a negative `tabindex` is not
 * entered) and follows the assigned nodes of a slot.
 */
const getTabbableCandidates = (container: HTMLElement): FocusableElement[] => {
  const nodes: FocusableElement[] = [];

  const visit = (element: Element) => {
    if (!(element instanceof HTMLElement || element instanceof SVGElement)) {
      return;
    }

    if (
      element instanceof HTMLElement &&
      (element.hidden !== false || element.inert)
    ) {
      return;
    }

    const { shadowRoot } = element;

    const isHiddenInput =
      element instanceof HTMLInputElement && element.type === "hidden";

    const isDisabled = "disabled" in element && Boolean(element.disabled);

    if (
      !isDisabled &&
      !isHiddenInput &&
      element.tabIndex >= 0 &&
      shadowRoot?.delegatesFocus !== true
    ) {
      nodes.push(element);
    }

    if (
      shadowRoot &&
      element.hasAttribute("tabindex") &&
      element.tabIndex < 0
    ) {
      return;
    }

    let children: Iterable<Element> = element.children;

    if (shadowRoot) {
      ({ children } = shadowRoot);
    } else if (element instanceof HTMLSlotElement) {
      children = element.assignedElements({ flatten: true });
    }

    for (const child of children) {
      visit(child);
    }
  };

  for (const child of container.children) {
    visit(child);
  }

  return nodes;
};

/** The first candidate that is visible. */
const findVisible = (
  elements: readonly FocusableElement[],
  container: HTMLElement
) => {
  const containerIsVisible =
    // oxlint-disable-next-line anti-slop/no-runtime-typeof -- The component checks that the browser has checkVisibility before using it.
    typeof container.checkVisibility === "function" &&
    container.checkVisibility({ checkVisibilityCSS: true });

  return elements.find((element) =>
    containerIsVisible
      ? element.checkVisibility({ checkVisibilityCSS: true })
      : !isHidden(element, container)
  );
};

const getTabbableEdges = (container: HTMLElement) => {
  const candidates = getTabbableCandidates(container);

  return [
    findVisible(candidates, container),
    findVisible(candidates.toReversed(), container),
  ] as const;
};

/** Radix `focus`: focuses without scrolling, and selects an input's text when asked. */
const focusElement = (
  element: FocusableElement | null | undefined,
  options?: { select?: boolean }
) => {
  if (isNil(element)) {
    return;
  }

  const previous = deepActiveElement();
  element.focus({ preventScroll: true });

  if (
    options?.select === true &&
    element !== previous &&
    element instanceof HTMLInputElement
  ) {
    element.select();
  }
};

/** Radix `focusFirst` over candidates, links removed as `removeLinks` does. */
const focusFirstCandidate = (container: HTMLElement) => {
  const candidates = getTabbableCandidates(container).filter(
    (element) => element.tagName !== "A"
  );

  const previous = deepActiveElement();

  for (const candidate of candidates) {
    focusElement(candidate, { select: true });

    if (deepActiveElement() !== previous) {
      return;
    }
  }
};

/**
 * The Tab loop of the Radix FocusScope with `loop` on: Tab on the last
 * tabbable focuses the first and Shift+Tab on the first tabbable, or on the
 * scope itself, focuses the last.
 */
const loopTabKey = (event: ReactKeyboardEvent<HTMLElement>) => {
  const isTab =
    event.key === "Tab" && !event.altKey && !event.ctrlKey && !event.metaKey;

  const focused = deepActiveElement();

  if (!isTab || !focused) {
    return;
  }

  const container = event.currentTarget;
  const [first, last] = getTabbableEdges(container);

  if (!(first && last)) {
    if (focused === container) {
      event.preventDefault();
    }

    return;
  }

  if (!event.shiftKey && focused === last) {
    event.preventDefault();
    focusElement(first, { select: true });
  } else if (event.shiftKey && (focused === first || focused === container)) {
    event.preventDefault();
    focusElement(last, { select: true });
  }
};

/* ------------------------------------------------------------- Escape stack --- */

interface EscapeEntry {
  callback: RefObject<() => void>;
  id: symbol;
}

let escapeStack: EscapeEntry[] = [];
let escapeListening = false;

const onEscapeKey = (event: KeyboardEvent) => {
  if (event.key !== "Escape") {
    return;
  }

  const [top] = escapeStack;

  if (top !== undefined) {
    event.preventDefault();
    top.callback.current();
  }
};

const syncEscapeListener = () => {
  if (escapeStack.length > 0 && !escapeListening) {
    document.body.addEventListener("keydown", onEscapeKey);
    escapeListening = true;
  } else if (escapeStack.length === 0 && escapeListening) {
    document.body.removeEventListener("keydown", onEscapeKey);
    escapeListening = false;
  }
};

/**
 * One body keydown listener runs the
 * callback of the most recently opened registrant on Escape and prevents the
 * default.
 */
const useEscapeStack = (active: boolean, onEscape: () => void) => {
  const latest = useLatest(onEscape);

  useEffect(() => {
    if (!active) {
      return noCleanup;
    }

    const entry: EscapeEntry = { callback: latest, id: Symbol("escape") };
    escapeStack.unshift(entry);
    syncEscapeListener();

    return () => {
      escapeStack = escapeStack.filter((item) => item.id !== entry.id);
      syncEscapeListener();
    };
  }, [active, latest]);
};

/* ------------------------------------------------------------ focus scopes --- */

/**
 * The focus scopes stack, shared by every
 * family whose content mounts a FocusScope: dialog, modal, menu, submenu and
 * popover. The newest scope is active and every older one is paused, so a
 * dialog or menu opened above a modal popover holds focus alone and the
 * popover's trap resumes when it closes.
 */
const focusScopes: FocusScope[] = [];

/** A Radix FocusScope on the shared stack: paused while a newer one is on top. */
interface FocusScope {
  paused: boolean;
}

interface FocusScopeOwner {
  ref: RefCallback<Element>;
  scope: FocusScope;
}

const addFocusScope = (scope: FocusScope) => {
  const [top] = focusScopes;

  if (top !== undefined && top !== scope) {
    top.paused = true;
  }

  const index = focusScopes.indexOf(scope);

  if (index !== -1) {
    focusScopes.splice(index, 1);
  }

  focusScopes.unshift(scope);
};

const removeFocusScope = (scope: FocusScope) => {
  const index = focusScopes.indexOf(scope);

  if (index !== -1) {
    focusScopes.splice(index, 1);
  }

  const [top] = focusScopes;

  if (top !== undefined) {
    top.paused = false;
  }
};

/** Pending removal timers, set when a scope's content leaves. */
const pendingRemovals = new WeakMap<FocusScope, number>();

/** The content mounted: join the stack, or cancel the removal a re-attach interrupted. */
const joinFocusScope = (scope: FocusScope) => {
  const pending = pendingRemovals.get(scope);

  if (pending === undefined) {
    addFocusScope(scope);

    return;
  }

  window.clearTimeout(pending);
  pendingRemovals.delete(scope);
};

/** The content left: Radix removes the scope in the next task. */
const leaveFocusScope = (scope: FocusScope) => {
  pendingRemovals.set(
    scope,
    window.setTimeout(() => {
      pendingRemovals.delete(scope);
      removeFocusScope(scope);
    }, 0)
  );
};

/**
 * Registers the content element it receives with the shared focus scopes
 * stack. The scope joins in the commit that attaches the
 * element, before any effect moves focus into it, and leaves in the next task
 * after the element is gone, as Radix removes it after the unmount autofocus.
 * Re-attaching in the same task (a merged ref that changes identity) keeps the
 * scope where it is.
 */
const useFocusScope = (): FocusScopeOwner => {
  const scope = useMemo<FocusScope>(() => ({ paused: false }), []);

  const ref = useCallback(
    (element: Element | null) => {
      if (!element) {
        return noCleanup;
      }

      joinFocusScope(scope);

      return () => {
        leaveFocusScope(scope);
      };
    },
    [scope]
  );

  return { ref, scope };
};

/* ------------------------------------------------------------ small hooks --- */

/** A media query, false on the server. */
const useMediaQuery = (query: string): boolean => {
  const subscribe = useCallback(
    (listener: () => void) => {
      const list = window.matchMedia(query);
      list.addEventListener("change", listener);

      return () => {
        list.removeEventListener("change", listener);
      };
    },
    [query]
  );

  return useSyncExternalStore(
    subscribe,
    () => window.matchMedia(query).matches,
    () => false
  );
};

/** True after the first client render. */
const useIsClient = (): boolean =>
  useSyncExternalStore(
    () => () => {
      // The value never changes after hydration.
    },
    () => true,
    () => false
  );

/**
 * Runs the callback after two animation frames, or
 * after a timeout when the page is hidden. Returns the cancel function.
 */
const afterFrames = (task: () => void, frames = 2): (() => void) => {
  if (
    // oxlint-disable-next-line anti-slop/no-runtime-typeof -- The component checks that the browser has requestAnimationFrame before using it.
    typeof window.requestAnimationFrame !== "function" ||
    document.visibilityState === "hidden"
  ) {
    const timer = setTimeout(task, 0);

    return () => {
      clearTimeout(timer);
    };
  }

  let remaining = frames;
  let handle = 0;

  const step = () => {
    remaining -= 1;

    if (remaining === 0) {
      task();
    } else {
      handle = window.requestAnimationFrame(step);
    }
  };

  handle = window.requestAnimationFrame(step);

  return () => {
    window.cancelAnimationFrame(handle);
  };
};

export {
  AUTOFOCUS_ON_MOUNT,
  AUTOFOCUS_ON_UNMOUNT,
  afterFrames,
  focusElement,
  focusFirstCandidate,
  getTabbableCandidates,
  isNil,
  loopTabKey,
  mergeRefs,
  containsDeep,
  deepActiveElement,
  useEscapeStack,
  useFocusScope,
  useIsClient,
  useMediaQuery,
};

export type { FocusScope };

"use client";

// Lucide artwork is covered by components/icon/lucide.license.

/* oxlint-disable react/no-clone-element, anti-slop/no-runtime-typeof, shadcn/no-arbitrary-values, shadcn/no-restyle -- The Modal dialog host and the shell restyle one frame with measured values. */
/* oxlint-disable complexity -- DialogLayout and DialogShell keep one branch per case. */
/* oxlint-disable shadcn/require-static-classes -- The image sheet and frame classes come from the dialog CSS module. */

import { DataButton } from "@/components/button/data-button";
import {
  isNil,
  mergeRefs,
  useIsClient,
} from "@/components/dialog/dialog-layer";
import {
  Modal,
  useModalRequestClose,
} from "@/components/dialog/modal";
import { createIcon } from "@/components/icon";
import { Button } from "@/components/ui/button";
import {
  Dialog,
  DialogBody,
  DialogDescription,
  DialogFooter,
  DialogHeader,
  DialogPortalContainerProvider,
  DialogTitle,
  useOverlayOwner,
} from "@/components/ui/dialog";
import type {
  DialogProps,
  DialogSize,
  DialogVariant,
} from "@/components/ui/dialog";
import type { LayerEvent } from "@/lib/dismissable-layer";
import { noCleanup } from "@/lib/dismissable-layer";
import { cn } from "@/lib/utils";
import { useCallback, useLayoutEffect, useRef, useState } from "react";
import type {
  ComponentProps,
  ReactNode,
  Ref,
  SubmitEvent as ReactSubmitEvent,
} from "react";
import { createPortal } from "react-dom";

import styles from "@/components/ui/dialog.module.css";

const DEFAULT_CLOSE_LABEL = "Close dialog";

const ModalCloseGlyph = createIcon({
  body: '<g fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><path d="M18 6 6 18"></path><path d="m6 6 12 12"></path></g>',
  canvas: { height: 20, viewBox: "0 0 24 24", width: 20 },
  name: "xmark-20",
});

const SheetCloseGlyph = createIcon({
  body: '<g fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><path d="M18 6 6 18"></path><path d="m6 6 12 12"></path></g>',
  canvas: { height: 24, viewBox: "0 0 24 24", width: 24 },
  name: "xmark-24",
});

/** The link glyph. */
const LinkGlyph = createIcon({
  body: '<g fill="none" stroke="currentColor" stroke-width="1.5" stroke-linecap="round" stroke-linejoin="round"><path d="M10 13a5 5 0 0 0 7.54.54l3-3a5 5 0 0 0-7.07-7.07l-1.72 1.71"></path><path d="M14 11a5 5 0 0 0-7.54-.54l-3 3a5 5 0 0 0 7.07 7.07l1.71-1.71"></path></g>',
  canvas: { height: 16, viewBox: "0 0 24 24", width: 16 },
  name: "link-16",
});

/* ------------------------------------------------------- scroll fade --- */

type ScrollFadeKind = "divider" | "mask" | "overlay";

interface ScrollFadeProps {
  children?: ReactNode;
  className?: string;
  /** `overlay` (default), `divider` or `mask`. */
  fade?: ScrollFadeKind;
  fadeClassName?: string;
  onOverflowChange?: (overflow: boolean) => void;
  /** Sizes the scroll area to a whole number of menu items. */
  peekMenuItems?: boolean;
  scrollClassName?: string;
  scrollProps?: ComponentProps<"div">;
}

const MENU_ITEMS =
  '[role="menuitem"], [role="menuitemcheckbox"], [role="menuitemradio"]';

/**
 * A scroll area that reports overflow and
 * the scroll direction as data attributes, and shows a divider, an overlay
 * or a mask at an edge that can still scroll.
 */
const ScrollFade = ({
  children,
  className,
  fade = "overlay",
  fadeClassName,
  onOverflowChange,
  peekMenuItems = false,
  scrollClassName,
  scrollProps,
}: ScrollFadeProps) => {
  const rootRef = useRef<HTMLDivElement>(null);
  const scrollRef = useRef<HTMLDivElement>(null);
  const innerRef = useRef<HTMLDivElement>(null);
  const latestOverflow = useRef(onOverflowChange);

  useLayoutEffect(() => {
    latestOverflow.current = onOverflowChange;
  });

  const maxHeightProp = scrollProps?.style?.maxHeight;

  useLayoutEffect(() => {
    const root = rootRef.current;
    const scroll = scrollRef.current;
    const inner = innerRef.current;

    if (isNil(root) || isNil(scroll) || isNil(inner)) {
      return noCleanup;
    }

    const report = () => {
      const overflow =
        (fade === "overlay" ? inner : scroll).scrollHeight >
        scroll.clientHeight + 1;

      const canScrollDown =
        scroll.scrollTop + scroll.clientHeight < scroll.scrollHeight - 1;

      latestOverflow.current?.(overflow);
      root.dataset.ckHasOverflow = overflow ? "true" : "false";
      root.dataset.ckCanScrollUp = scroll.scrollTop > 1 ? "true" : "false";
      root.dataset.ckCanScrollDown =
        overflow && canScrollDown ? "true" : "false";
    };

    const originalMaxHeight = scroll.style.maxHeight;
    let peekMaxHeight: string | undefined;

    const update = () => {
      if (peekMenuItems) {
        const { scrollTop } = scroll;
        scroll.style.maxHeight = originalMaxHeight;
        peekMaxHeight = undefined;
        const { clientHeight } = scroll;

        if (scroll.scrollHeight > clientHeight + 1) {
          const box = scroll.getBoundingClientRect();
          const scale = box.height / scroll.offsetHeight;
          let fitting = 0;

          if (scale > 0) {
            for (const item of inner.querySelectorAll(MENU_ITEMS)) {
              const rect = item.getBoundingClientRect();

              const middle =
                (rect.top - box.top + rect.height / 2) / scale -
                scroll.clientTop +
                scroll.scrollTop;

              if (rect.height > 0 && middle <= clientHeight) {
                fitting = Math.max(fitting, middle);
              }
            }
          }

          if (fitting > 0) {
            peekMaxHeight = `${fitting}px`;
            scroll.style.maxHeight = peekMaxHeight;
          }
        }

        scroll.scrollTop = scrollTop;
      }

      report();
    };

    update();
    scroll.addEventListener("scroll", report, { passive: true });

    const resize =
      typeof ResizeObserver === "undefined"
        ? undefined
        : new ResizeObserver(update);

    resize?.observe(scroll);
    resize?.observe(inner);
    const mutation = peekMenuItems ? new MutationObserver(update) : undefined;
    mutation?.observe(inner, {
      characterData: true,
      childList: true,
      subtree: true,
    });

    if (peekMenuItems) {
      window.addEventListener("resize", update);
    }

    return () => {
      scroll.removeEventListener("scroll", report);
      resize?.disconnect();
      mutation?.disconnect();
      window.removeEventListener("resize", update);

      if (scroll.style.maxHeight === peekMaxHeight) {
        scroll.style.maxHeight = originalMaxHeight;
      }
    };
    // oxlint-disable-next-line react/exhaustive-effect-dependencies -- The effect reads the scroll element's inline max-height, which follows this prop, so it must run again when the prop changes ().
  }, [fade, peekMenuItems, maxHeightProp]);

  return (
    <div
      className={cn("group", styles.scrollFadeRoot, className)}
      data-ck-can-scroll-down="false"
      data-ck-can-scroll-up="false"
      data-ck-has-overflow="false"
      ref={rootRef}
    >
      <div
        {...scrollProps}
        className={cn(
          fade === "mask" && styles.scrollFadeMask,
          scrollClassName,
          scrollProps?.className
        )}
        ref={mergeRefs<HTMLDivElement>(scrollRef, scrollProps?.ref)}
      >
        <div ref={innerRef}>{children}</div>
      </div>
      {fade === "divider" && (
        <>
          <div
            aria-hidden="true"
            className="pointer-events-none absolute inset-x-0 top-0 hidden border-t border-stroke-subtle group-data-[can-scroll-up=true]:block"
          />
          <div
            aria-hidden="true"
            className="pointer-events-none absolute inset-x-0 bottom-0 hidden border-t border-stroke-subtle group-data-[can-scroll-down=true]:block"
          />
        </>
      )}
      {fade === "overlay" && (
        <div
          className={cn(
            "pointer-events-none absolute bottom-0 hidden h-10 bg-linear-to-b from-transparent to-panel-elevated-secondary/90 group-data-[can-scroll-down=true]:block",
            fadeClassName
          )}
        />
      )}
    </div>
  );
};

/* ------------------------------------------------------ dialog layout --- */

type DialogLayoutVariant = "compact" | "default" | "sectioned";

interface DialogLayoutProps {
  children?: ReactNode;
  /** With no children, the scrolling body row is dropped. */
  collapseEmptyContent?: boolean;
  footer?: ReactNode;
  header?: ReactNode;
  headerContent?: ReactNode;
  onSubmit?: (event: ReactSubmitEvent<HTMLFormElement>) => void;
  variant?: DialogLayoutVariant;
}

/**
 * A grid of a header row, a scrolling
 * body row and a footer row. With `onSubmit` the grid is a form.
 */
const DialogLayout = ({
  children,
  collapseEmptyContent = false,
  footer,
  header,
  headerContent,
  onSubmit,
  variant = "default",
}: DialogLayoutProps) => {
  const collapsed = collapseEmptyContent && isNil(children);
  const compact = variant === "compact";
  const sectioned = variant === "sectioned";
  const plain = variant === "default";

  const content = compact ? (
    <ScrollFade
      className="relative -mx-5 -mt-2 flex min-h-0 flex-col"
      fade="divider"
      scrollClassName="min-h-0 overflow-y-auto overscroll-contain px-5 pt-2 pb-5"
    >
      {header}
      {!isNil(headerContent) && <div className="pt-5">{headerContent}</div>}
      {!isNil(children) && <div className="pt-5">{children}</div>}
    </ScrollFade>
  ) : (
    <>
      <div
        className={cn(
          "min-h-0 overflow-y-auto overscroll-contain",
          plain && "-mt-2 pt-2"
        )}
      >
        <div className={cn(sectioned && "ps-6 pe-4 pt-4")}>{header}</div>
        {!isNil(headerContent) && (
          <div className="px-6 pt-4 empty:hidden">{headerContent}</div>
        )}
      </div>
      {collapsed ? null : (
        <ScrollFade
          className={cn(
            "relative flex flex-col",
            plain && "-mx-5 min-h-24",
            sectioned && "min-h-0"
          )}
          fade="divider"
          scrollClassName={cn(
            "min-h-0 overflow-y-auto overscroll-contain",
            sectioned && "px-6",
            plain && "px-5"
          )}
        >
          <div
            className={cn(
              sectioned && cn("pb-6", isNil(headerContent) ? "pt-4" : "pt-6"),
              plain && "py-5"
            )}
          >
            {children}
          </div>
        </ScrollFade>
      )}
    </>
  );

  const rows = cn(
    "grid grid-cols-1",
    compact && "grid-rows-[minmax(0,1fr)_auto]",
    !compact &&
      (collapsed
        ? "grid-rows-[minmax(0,max-content)_auto]"
        : "grid-rows-[minmax(0,max-content)_1fr_auto]")
  );

  return (
    <DialogBody
      as={isNil(onSubmit) ? "div" : "form"}
      className={rows}
      size="scrollable"
      variant={sectioned ? "sectioned" : "default"}
      onSubmit={onSubmit}
    >
      {content}
      {sectioned && !isNil(footer) && (
        <Modal.Footer className="flex-wrap">{footer}</Modal.Footer>
      )}
      {!sectioned && (
        <DialogFooter className="shrink-0 flex-wrap" expandSingleButton={false}>
          {footer}
        </DialogFooter>
      )}
    </DialogBody>
  );
};

/* -------------------------------------------------------- Modal dialog --- */

interface ModalDialogContentProps {
  children?: ReactNode;
  footer?: ReactNode;
  headerActions?: ReactNode;
  headerContent?: ReactNode;
  /** Locks the close button and denies every close request. */
  isDismissalDisabled?: boolean;
  /** With no footer, shows a disabled "Copy link" and "Done" pair. */
  isLoading?: boolean;
  /** Called when a close is requested; answer `"deny"` to keep the dialog open. */
  onRequestClose?: () => "allow" | "deny" | undefined;
  onPortalContainerChange?: Ref<HTMLDivElement>;
  onSubmit?: () => void;
  subtitle?: ReactNode;
  title?: ReactNode;
  variant?: DialogLayoutVariant;
  /** Breaks a long title over lines instead of truncating it. */
  wrapTitle?: boolean;
}

/** The title row, close button and footer of a Modal dialog. */
const ModalDialogContent = ({
  children,
  footer,
  headerActions,
  headerContent,
  isDismissalDisabled = false,
  isLoading = false,
  onPortalContainerChange,
  onRequestClose,
  onSubmit,
  subtitle,
  title,
  variant = "sectioned",
  wrapTitle = false,
}: ModalDialogContentProps) => {
  const requestClose = () =>
    isDismissalDisabled ? "deny" : (onRequestClose?.() ?? "allow");

  const { close } = useModalRequestClose({ onRequestClose: requestClose });

  const headerRow = (
    <div className="flex items-start gap-3">
      <DialogHeader
        className="min-w-0 flex-1"
        subtitle={
          isNil(subtitle) || variant === "compact" ? undefined : (
            <Modal.Description className="contents">
              {subtitle}
            </Modal.Description>
          )
        }
        title={<Modal.Title className="contents">{title}</Modal.Title>}
        titleClassName={wrapTitle ? "break-words" : "truncate"}
      />
      <div className="relative -top-1 flex shrink-0 items-center gap-3">
        {headerActions}
        <DataButton
          aria-label={DEFAULT_CLOSE_LABEL}
          color="primary"
          disabled={isDismissalDisabled}
          iconSize="lg"
          size="xl"
          uniform
          variant="ghost"
          onClick={() => {
            if (requestClose() === "allow") {
              close();
            }
          }}
        >
          <ModalCloseGlyph />
        </DataButton>
      </div>
      {isNil(subtitle) && (
        <Modal.Description className="sr-only">{subtitle}</Modal.Description>
      )}
    </div>
  );

  const header = (
    <>
      {headerRow}
      {variant === "compact" && !isNil(subtitle) && (
        <div className="pt-6 text-text-subtle">
          <Modal.Description className="contents">{subtitle}</Modal.Description>
        </div>
      )}
    </>
  );

  const bottom =
    isLoading && isNil(footer) ? (
      <>
        <div className="me-auto">
          <DataButton
            color="primary"
            disabled
            size="xl"
            type="button"
            variant="outline"
          >
            <LinkGlyph />
            Copy link
          </DataButton>
        </div>
        <Modal.Close>
          <DataButton
            color="primary"
            disabled={isDismissalDisabled}
            size="xl"
            type="button"
          >
            Done
          </DataButton>
        </Modal.Close>
      </>
    ) : (
      footer
    );

  return (
    <DialogLayout
      footer={bottom}
      header={header}
      headerContent={headerContent}
      variant={variant}
      onSubmit={
        isNil(onSubmit)
          ? undefined
          : (event) => {
              event.preventDefault();
              event.stopPropagation();

              if (!isDismissalDisabled && !isLoading) {
                onSubmit();
              }
            }
      }
    >
      {variant === "compact" && isNil(children) ? null : (
        <div className="contents" ref={onPortalContainerChange}>
          {children}
        </div>
      )}
    </DialogLayout>
  );
};

interface ModalDialogHostProps {
  animateOnMount?: boolean;
  children?: ReactNode;
  onClose?: () => void;
  onCloseAutoFocus?: (event: LayerEvent) => void;
  /** Keeps the dialog's top edge still while its height changes. */
  preserveTopOnResize?: boolean;
}

/** A fixed viewport layer holding an open Modal. */
const ModalDialogHost = ({
  animateOnMount = true,
  children,
  onClose,
  onCloseAutoFocus,
  preserveTopOnResize = false,
}: ModalDialogHostProps) => {
  const [container, setContainer] = useState<HTMLDivElement | null>(null);
  const previouslyFocused = useRef<HTMLElement | null | undefined>(undefined);
  const owner = useOverlayOwner();
  const isClient = useIsClient();

  useLayoutEffect(() => {
    const dialog = container?.querySelector<HTMLElement>('[role="dialog"]');
    const parent = dialog?.parentElement;

    if (
      !preserveTopOnResize ||
      isNil(dialog) ||
      isNil(parent) ||
      typeof ResizeObserver === "undefined"
    ) {
      return noCleanup;
    }

    let height = dialog.offsetHeight;
    let anchorHeight: number | undefined;
    let width = dialog.offsetWidth;
    let parentHeight = parent.clientHeight;

    const observer = new ResizeObserver((entries) => {
      height =
        entries.find((entry) => entry.target === dialog)?.borderBoxSize[0]
          ?.blockSize ?? height;

      if (isNil(anchorHeight)) {
        anchorHeight = height;
      }

      if (getComputedStyle(dialog).position !== "static") {
        dialog.style.removeProperty("translate");

        return;
      }

      if (
        dialog.offsetWidth !== width ||
        parent.clientHeight !== parentHeight
      ) {
        anchorHeight = height;
        width = dialog.offsetWidth;
        parentHeight = parent.clientHeight;
      }

      const padding =
        // oxlint-disable-next-line unicorn/prefer-number-coercion -- The padding is a length such as "16px", which Number cannot read.
        Number.parseFloat(getComputedStyle(parent).paddingBottom) || 0;

      const shift = Math.min(
        (height - anchorHeight) / 2,
        Math.max(0, (parent.clientHeight - height) / 2 - padding)
      );

      dialog.style.translate = `0 ${shift}px`;
    });

    observer.observe(dialog);
    observer.observe(parent);

    return () => {
      observer.disconnect();
      dialog.style.removeProperty("translate");
    };
  }, [container, preserveTopOnResize]);

  const attach = useCallback((element: HTMLDivElement | null) => {
    if (!isNil(element) && isNil(previouslyFocused.current)) {
      const active = element.ownerDocument.activeElement;
      previouslyFocused.current =
        active instanceof HTMLElement &&
        active !== element.ownerDocument.body &&
        active !== element.ownerDocument.documentElement
          ? active
          : null;
    }

    if (!isNil(element)) {
      setContainer(element);
    }
  }, []);

  if (!isClient) {
    return null;
  }

  return createPortal(
    <div
      className="fixed inset-0 z-50 h-[calc(100dvh/var(--ui-display-scale,1))] w-[calc(100vw/var(--ui-display-scale,1))] [zoom:var(--ui-display-scale,1)] contain-layout"
      data-ck-overlay-owner={owner?.id}
      ref={attach}
    >
      {!isNil(container) && (
        <DialogPortalContainerProvider value={container}>
          <Modal defaultOpen>
            <Modal.Content
              animateOnMount={animateOnMount}
              className="bg-[light-dark(var(--ck-palette-surface-surface),var(--ck-palette-surface-editor-opaque))]"
              maxWidth={512}
              onAfterClose={onClose}
              onCloseAutoFocus={(event) => {
                const active = container.ownerDocument.activeElement;

                if (
                  active === container.ownerDocument.body ||
                  container.contains(active)
                ) {
                  onCloseAutoFocus?.(event);

                  if (
                    !event.defaultPrevented &&
                    previouslyFocused.current?.isConnected === true
                  ) {
                    previouslyFocused.current.focus({ preventScroll: true });
                  }
                }

                event.preventDefault();
              }}
            >
              {children}
            </Modal.Content>
          </Modal>
        </DialogPortalContainerProvider>
      )}
    </div>,
    document.body
  );
};

interface ModalDialogProps
  extends
    ModalDialogContentProps,
    Omit<ModalDialogHostProps, "children" | "onCloseAutoFocus"> {}

/** A Modal dialog with a title, close button, body and footer. */
const ModalDialog = ({
  animateOnMount,
  onClose,
  preserveTopOnResize,
  ...content
}: ModalDialogProps) => (
  <ModalDialogHost
    animateOnMount={animateOnMount}
    preserveTopOnResize={preserveTopOnResize}
    onClose={onClose}
  >
    <ModalDialogContent {...content} />
  </ModalDialogHost>
);

/* -------------------------------------------------------- dialog shell --- */

interface DialogShellProps {
  children?: ReactNode;
  collapseEmptyContent?: boolean;
  compactImageSheetFooter?: boolean;
  footer?: ReactNode;
  headerActions?: ReactNode;
  headerContent?: ReactNode;
  isDismissalDisabled?: boolean;
  onClose: () => void;
  onCloseAutoFocus?: (event: LayerEvent) => void;
  onOpenAutoFocus?: (event: LayerEvent) => void;
  onPortalContainerChange?: (element: HTMLElement) => void;
  onSubmit?: () => void;
  presentation?: "imageSheet";
  size?: DialogSize;
  subtitle?: ReactNode;
  title?: ReactNode;
  variant?: DialogVariant;
}

/**
 * The standard shell, an open
 * Dialog with a title, optional subtitle, form submit and a lock that stops
 * every close. `presentation="imageSheet"` draws the image sheet.
 */
const DialogShell = ({
  children,
  collapseEmptyContent = false,
  compactImageSheetFooter = false,
  footer,
  headerActions,
  headerContent,
  isDismissalDisabled = false,
  onClose,
  onCloseAutoFocus,
  onOpenAutoFocus,
  onPortalContainerChange,
  onSubmit,
  presentation,
  size,
  subtitle,
  title,
  variant,
}: DialogShellProps) => {
  const imageSheet = presentation === "imageSheet";

  const handleSubmit = (event: ReactSubmitEvent<HTMLFormElement>) => {
    event.preventDefault();
    event.stopPropagation();

    if (!isDismissalDisabled) {
      onSubmit?.();
    }
  };

  const heading = imageSheet ? (
    <div
      className={cn(
        "shrink-0",
        styles.imageSheetHeader,
        compactImageSheetFooter && styles.imageSheetTwoRowsHeader
      )}
    >
      <DialogTitle className={styles.imageSheetTitle}>{title}</DialogTitle>
      {!isNil(subtitle) && (
        <DialogDescription className={styles.imageSheetSubtitle}>
          {subtitle}
        </DialogDescription>
      )}
      {!isDismissalDisabled && (
        <Button
          aria-label={DEFAULT_CLOSE_LABEL}
          className={cn(
            styles.imageSheetClose,
            compactImageSheetFooter && styles.imageSheetTwoRowsClose
          )}
          unstyled
          onClick={(event) => {
            event.stopPropagation();
            onClose();
          }}
        >
          <SheetCloseGlyph />
        </Button>
      )}
    </div>
  ) : (
    <div className="mb-2 flex items-center gap-2 pe-8">
      <DialogHeader
        className="min-w-0 flex-1"
        subtitle={
          isNil(subtitle) ? undefined : (
            <DialogDescription className="contents">
              {subtitle}
            </DialogDescription>
          )
        }
        title={<DialogTitle className="contents">{title}</DialogTitle>}
        titleClassName="truncate"
      />
      {headerActions}
    </div>
  );

  const header = (
    <>
      {heading}
      {headerContent}
    </>
  );

  const contentProps: NonNullable<DialogProps["contentProps"]> = {
    ...(isNil(subtitle) ? { "aria-describedby": undefined } : null),
    onCloseAutoFocus,
    onOpenAutoFocus: (event) => {
      if (event.currentTarget instanceof HTMLElement) {
        onPortalContainerChange?.(event.currentTarget);
      }

      onOpenAutoFocus?.(event);
    },
    shouldStopPointerDownPropagation: false,
  };

  return (
    <Dialog
      contentClassName={imageSheet ? styles.imageSheetSurface : undefined}
      contentOverflow="visible"
      contentProps={contentProps}
      open
      overlayClassName={imageSheet ? styles.imageSheetOverlay : undefined}
      shouldIgnoreClickOutside={isDismissalDisabled}
      showDialogClose={!isDismissalDisabled && !imageSheet}
      size={size}
      unstyledContent={imageSheet}
      variant={variant ?? "opaque"}
      onOpenChange={(open) => {
        if (!open && !isDismissalDisabled) {
          onClose();
        }
      }}
    >
      {imageSheet ? (
        <DialogBody
          as={isNil(onSubmit) ? "div" : "form"}
          className={cn(
            styles.imageSheetBody,
            "min-h-0",
            compactImageSheetFooter && styles.imageSheetTwoRowsBody
          )}
          variant="sectioned"
          onSubmit={isNil(onSubmit) ? undefined : handleSubmit}
        >
          <div className="flex min-h-0 flex-col">
            {header}
            {children}
          </div>
          <div
            className={cn(
              "shrink-0",
              compactImageSheetFooter ? "mt-2" : "mt-12"
            )}
          >
            {footer}
          </div>
        </DialogBody>
      ) : (
        <DialogLayout
          collapseEmptyContent={collapseEmptyContent}
          footer={footer}
          header={header}
          onSubmit={isNil(onSubmit) ? undefined : handleSubmit}
        >
          {children}
        </DialogLayout>
      )}
    </Dialog>
  );
};

