    backdrop-filter: blur(1px);
  }

  .dimmedOverlay {
    backdrop-filter: blur(1px);
    background: light-dark(
      color-mix(in srgb, var(--ck-palette-surface-surface) 50%, transparent),
      color-mix(in srgb, var(--ck-shadow-color) 50%, transparent)
    );
  }

  .voicePickerOverlay {
    backdrop-filter: blur(1px);
    background: light-dark(
      color-mix(in srgb, var(--ck-palette-surface-surface) 50%, transparent),
      color-mix(in srgb, var(--ck-shadow-color) 50%, transparent)
    );
  }

  .promotionalSheetOverlay {
    background: light-dark(
      color-mix(in srgb, var(--ck-palette-surface-surface) 50%, transparent),
      color-mix(in srgb, var(--ck-shadow-color) 50%, transparent)
