    backdrop-filter: blur(1px);
  }

  .imageOverlay[data-transparent="true"] {
    backdrop-filter: blur(var(--blur-xs, 4px));
  }

  /* ---------------------------------------------------------------- surfaces */

  .catalogSurface {
    --font-weight-medium: 510;
    --font-weight-semibold: 590;
    border-radius: 24px;
    box-shadow: 0 20px 25px -5px
      color-mix(in srgb, var(--ck-shadow-color) 10%, transparent);
  }

  .catalogCompact {
    border-radius: 16px;
  }

  .creditCheckoutSurface {
    box-shadow:
      inset 0 0 0 1px var(--border),
      0 20px 25px -5px
        color-mix(in srgb, var(--ck-shadow-color) 10%, transparent);
  }

  .creditCheckoutSurface[data-ck-checkout-theme="dark"] {
    box-shadow:
      inset 0 0 0 1px var(--border),
      0 8px 16px 0 color-mix(in srgb, var(--ck-shadow-color) 32%, transparent),
      inset 0 0 1px 0 color-mix(in srgb, var(--ck-fixed-white) 20%, transparent),
      0 0 1px 0 color-mix(in srgb, var(--ck-shadow-color) 62%, transparent);
  }

  .centeredTextSurface {
    outline: 1px solid var(--ck-palette-border-light);
    outline-offset: -1px;
  }

  .centeredTextClose {
    position: absolute;
