      var(--color-dark-app-text-foreground-tertiary)
    );
    --color-fill-primary-transparent-hover: light-dark(
      color-mix(in srgb, var(--ck-shadow-color) 5%, transparent),
      var(--ck-fixed-white) fff1a
    );
    border-radius: var(--radius-2xl);
    background-color: var(
      --ck-palette-surface-card,
      var(--ck-palette-surface-surface)
    );
    color: var(--ck-palette-ink);
    width: calc(100vw / var(--ui-display-scale, 1) - 2rem);
    max-width: calc(100vw / var(--ui-display-scale, 1) - 2rem);
    box-shadow: var(--ck-dialog-card-shadow);
  }

  @media (width >= 40rem) {
    .voicePickerSurface {
      width: max-content;
      min-width: min(400px, calc(100vw / var(--ui-display-scale, 1) - 2rem));
      max-width: min(576px, calc(100vw / var(--ui-display-scale, 1) - 2rem));
    }
  }

  .voicePickerClose {
    width: calc(var(--spacing, 0.25rem) * 9);
    height: calc(var(--spacing, 0.25rem) * 9);
    border-radius: var(--radius-lg);
    top: 24px;
    right: 24px;
  }

  .voicePickerClose:focus-visible {
    outline-offset: 0;
    outline: 1px auto;
  }

  /* ------------------------------------------------------------------ sheets */

  .responsiveSheet {
    display: grid;
    width: 100%;
    height: auto;
    max-width: var(--container-md, 28rem);
    border-top-left-radius: var(--radius-2xl);
    border-top-right-radius: var(--radius-2xl);
    inset-inline: 0;
    margin-inline: auto;
    bottom: 0;
    padding-bottom: env(safe-area-inset-bottom, 0px);
    grid-template-rows: min-content minmax(0, 1fr) min-content;
  }

  @media (width >= 40rem) {
    .responsiveSheet {
      translate: 0 -50%;
      border-radius: var(--radius-2xl);
      top: 50%;
      bottom: auto;
    }
  }

  .promotionalSheet {
    display: flex;
    flex-direction: column;
    width: calc(var(--spacing, 0.25rem) * 120);
    border-radius: var(--radius-3xl);
    max-width: 92vw;
    padding-bottom: 0;
  }

  @media not all and (width >= 40rem) {
    .promotionalSheet {
      bottom: max(calc(var(--spacing) * 2), env(safe-area-inset-bottom, 0px));
      width: calc(100vw / var(--ui-display-scale, 1) - var(--spacing) * 4);
      max-width: none;
      max-height: calc(
        100dvh / var(--ui-display-scale, 1) -
          max(calc(var(--spacing) * 2), env(safe-area-inset-bottom, 0px)) -
          var(--spacing) * 4
      );
      border-radius: 36px;
    }

    .edgeToEdgeSheet {
      width: calc(100vw / var(--ui-display-scale, 1));
      max-height: calc(100dvh / var(--ui-display-scale, 1));
      padding-bottom: env(safe-area-inset-bottom, 0px);
      border-radius: 40px 40px 0 0;
      bottom: 0;
    }
  }

  .promotionalSheetClose {
    top: calc(var(--spacing, 0.25rem) * 5);
    right: calc(var(--spacing, 0.25rem) * 5);
    background-color: var(--ck-palette-surface-surface);
    box-shadow: 0 1px 2px 0
      color-mix(in srgb, var(--ck-shadow-color) 5%, transparent);
  }

  .expressiveBeaconSurface {
    border-radius: 24px;
  }

  .expressiveBeaconTitle {
    letter-spacing: -0.36px;
    font-size: 20px;
    font-weight: 590;
    line-height: 28px;
  }

  @media not all and (width >= 40rem) {
    .responsiveExpressiveBeaconTitle {
      letter-spacing: -0.26px;
      font-size: 22px;
    }
  }

  .photoSetupPosition {
    top: 50%;
  }

  @media (width >= 48rem) {
    .photoSetupPosition {
      top: calc(50% - max(0px, 100dvh - var(--spacing) * 135) / 18);
    }
  }

  .splitCatalog,
  .catalogSetup {
    /* --white and --gray-300, --gray-950, --gray-500 and --gray-800 */
    --ck-palette-surface-surface: light-dark(
      var(--color-light-app-background-elevated-primary-opaque),
      var(--color-dark-app-background-elevated-primary-opaque)
    );
    --ck-palette-ink: light-dark(var(--color-light-ink), var(--color-dark-ink));
    --ck-palette-ink-secondary: light-dark(
      var(--color-light-app-text-foreground-secondary),
      var(--color-dark-app-text-foreground-secondary)
    );
    background: var(--ck-palette-surface-surface);
    color: var(--ck-palette-ink);
  }

  .splitCatalog {
    outline: 1px solid var(--border);
    outline-offset: -1px;
    display: flex;
    flex-direction: column;
    border-top-left-radius: var(--radius-2xl);
    border-top-right-radius: var(--radius-2xl);
    inset-inline: 0;
    margin-inline: auto;
    bottom: 0;
    width: calc(100dvw / var(--ui-display-scale, 1));
    height: min(500px, calc(100dvh / var(--ui-display-scale, 1) - 96px));
    padding-bottom: env(safe-area-inset-bottom, 0px);
  }

  @media (width >= 40rem) {
    .splitCatalog {
      height: min(500px, calc(100dvh / var(--ui-display-scale, 1) - 64px));
    }
  }

  @media (width >= 48rem) {
    .splitCatalog {
      translate: 0 -50%;
      border-radius: var(--radius-2xl);
      top: 50%;
      bottom: auto;
      width: min(860px, calc(100dvw / var(--ui-display-scale, 1) - 40px));
    }
  }

  .catalogSetup {
    border-top-left-radius: var(--radius-2xl);
    border-top-right-radius: var(--radius-2xl);
    inset-inline: 0;
    margin-inline: auto;
    bottom: 0;
    width: calc(100dvw / var(--ui-display-scale, 1));
    max-height: min(640px, calc(92dvh / var(--ui-display-scale, 1)));
  }

  @media (width >= 48rem) {
    .catalogSetup {
      translate: 0 -50%;
      border-radius: var(--radius-2xl);
      top: 50%;
      bottom: auto;
      width: min(520px, calc(100dvw / var(--ui-display-scale, 1) - 40px));
      max-height: min(640px, calc(95dvh / var(--ui-display-scale, 1) - 40px));
    }
  }

  /* ------------------------------------------------------- body/section/footer */

  .body {
    padding-inline: calc(var(--spacing, 0.25rem) * 5);
    padding-block: calc(var(--spacing, 0.25rem) * 5);
  }

  .section {
    padding-top: calc(var(--spacing, 0.25rem) * 3);
  }

  .largeSection {
    padding-top: calc(var(--spacing, 0.25rem) * 5);
  }

  .section:nth-child(1 of :not(:global(.sr-only))) {
    padding-top: 0;
  }

  .body > .footer:nth-child(n + 2 of :not(:global(.sr-only))) {
    margin-top: calc(var(--spacing, 0.25rem) * 5);
  }

  .checkoutConfirmationBody {
    padding: calc(var(--spacing, 0.25rem) * 6);
  }

  .checkoutConfirmationBody h2 {
    font-size: 17px;
    line-height: calc(var(--spacing, 0.25rem) * 6);
    font-weight: var(--font-weight-medium, 500);
    letter-spacing: -0.43px;
  }

  .checkoutConfirmationBody > .section + .section {
    padding-top: calc(var(--spacing, 0.25rem) * 2);
  }

  .checkoutConfirmationBody > .section:last-of-type {
    padding-top: calc(var(--spacing, 0.25rem) * 4);
  }

  .sectionedConfirmationBody {
    padding-inline: calc(var(--spacing, 0.25rem) * 6);
    padding-bottom: calc(var(--spacing, 0.25rem) * 6);
  }

  .sectionedConfirmationBody > .section:nth-of-type(2) {
    padding-top: 0;
  }

  .sectionedConfirmationBody > .section:first-of-type {
    padding-block: calc(var(--spacing, 0.25rem) * 4);
  }

  .sectionedConfirmationBody > .section:last-of-type {
    padding-top: calc(var(--spacing, 0.25rem) * 8);
  }

  .sectionedConfirmationHeaderTitle {
    display: flex;
    align-items: center;
    min-height: calc(var(--spacing, 0.25rem) * 9);
    font-size: var(--text-lg, 16px);
    line-height: calc(var(--spacing, 0.25rem) * 7);
    font-weight: var(--font-weight-medium, 500);
    letter-spacing: var(--tracking-normal, 0em);
  }

  /* ------------------------------------------------ transition group child */

  .transitionGroupChild {
    display: block;
  }

  /* ---------------------------------------------------- anchored large frame */

  .anchoredFrame {
    top: calc(
      50% -
        (
          100dvh / var(--ui-display-scale, 1) -
            min(
              calc(var(--spacing) * 115),
              calc(100dvh / var(--ui-display-scale, 1) - var(--spacing) * 10)
            )
        ) /
        18
    );
    left: 50%;
    transform: translate(-50%, -50%);
  }

  @media (width <= 47.999rem) {
    .anchoredFrame {
      inset: 0;
      transform: none;
    }
  }

  /* ------------------------------------------------------------ image sheet */

  .imageSheetBody {
    max-height: calc(100dvh / var(--ui-display-scale, 1) - 1rem);
    overscroll-behavior-y: contain;
    padding-bottom: max(28px, env(safe-area-inset-bottom));
    overflow: hidden auto;
  }

  .imageSheetTwoRowsBody {
    padding-bottom: 0;
  }

  .imageSheetSurface {
    --ck-palette-ink: light-dark(var(--color-light-ink), var(--color-dark-ink));
    --ck-palette-ink-secondary: light-dark(
      var(--color-light-app-text-foreground-secondary),
      var(--color-dark-app-text-foreground-secondary)
    );
    --ck-palette-ink-tertiary: light-dark(
      var(--color-light-app-text-foreground-tertiary),
      var(--color-dark-app-text-foreground-tertiary)
    );
    width: 100%;
    height: auto;
    color: var(--ck-palette-ink);
    inset-inline: 0;
    background: var(--ck-palette-surface-surface);
    border-radius: 40px 40px 0 0;
    padding-bottom: 0;
    font-family: var(--font-sans);
    bottom: 0;
    overflow: hidden;
    box-shadow: var(--ck-dialog-card-shadow);
  }

  .imageSheetOverlay:global(.overlay-layer) {
    /* Media scrim uses the theme ink. */
    background-color: color-mix(
      in oklab,
      var(--ck-palette-ink) 15%,
      transparent
    );
    backdrop-filter: blur(var(--blur-xs, 4px));
  }

  .imageSheetClose {
    position: absolute;
    justify-content: center;
    width: calc(var(--spacing, 0.25rem) * 9);
    height: calc(var(--spacing, 0.25rem) * 9);
    border-radius: var(--radius-pill, 9999px);
    color: var(--ck-palette-ink);
    background: light-dark(
      color-mix(in srgb, var(--ck-palette-surface-surface) 90%, transparent),
      color-mix(in srgb, var(--ck-palette-ink) 5%, transparent)
    );
    line-height: 1;
    top: 16px;
    inset-inline-end: 16px;
  }

  .imageSheetTwoRowsClose {
    width: 44px;
    height: 44px;
  }

  .imageSheetHeader {
    position: relative;
    padding-inline: calc(var(--spacing, 0.25rem) * 16);
    padding-bottom: calc(var(--spacing, 0.25rem) * 6);
    padding-top: 28px;
  }

  .imageSheetTwoRowsHeader {
    padding-top: 20px;
  }

  .imageSheetTitle {
    text-align: center;
    line-height: calc(var(--spacing, 0.25rem) * 7);
    font-weight: var(--font-weight-semibold, 600);
    letter-spacing: -0.44px;
    font-size: 20px;
  }

  .imageSheetSubtitle {
    text-align: center;
    color: var(--ck-palette-ink-secondary);
    letter-spacing: -0.08px;
    font-size: 14px;
    font-weight: 400;
    line-height: 20px;
  }

  /* ------------------------------------------------------------------ Modal */

  .modalPortal {
    -webkit-app-region: no-drag;
    pointer-events: auto;
    position: fixed;
    inset: 0;
  }

  .modalPortalInner {
    position: absolute;
    inset: 0;
  }

  .modalBackdrop {
    background-color: light-dark(
      color-mix(in srgb, var(--ck-shadow-color) 30%, transparent),
      color-mix(in srgb, var(--ck-shadow-color) 50%, transparent)
    );
    position: absolute;
    inset: 0;
  }

  [data-backdrop="fade"] .modalBackdrop {
    backdrop-filter: blur(1px);
    background-color: light-dark(
      color-mix(in srgb, var(--ck-palette-surface-surface) 50%, transparent),
      color-mix(in srgb, var(--ck-shadow-color) 50%, transparent)
    );
  }

  [data-entering] .modalBackdrop {
    opacity: 0;
  }

  [data-entering-active] .modalBackdrop,
  [data-entering][data-interrupted] .modalBackdrop {
    opacity: 1;
    transition-property: opacity, transform;
    transition-duration: 0.6s;
    transition-timing-function: var(--ck-curve-enter);
  }

  [data-exiting] .modalBackdrop {
    opacity: 1;
  }

  [data-exiting-active] .modalBackdrop,
  [data-exiting][data-interrupted] .modalBackdrop {
    opacity: 0;
    transition-property: opacity, transform;
    transition-duration: 0.4s;
    transition-timing-function: var(--ck-curve-exit);
  }

  .modalContainer {
    position: absolute;
    inset: 0;
  }

  @media (width >= 48rem) {
    .modalContainer[data-ck-modal-scroll="outside"] {
      overflow: auto;
    }
  }

  .modalContainerInner {
    position: absolute;
    inset: 0;
  }

  @media (width >= 48rem) {
    .modalContainerInner {
      inset: unset;
      display: flex;
      justify-content: center;
      align-items: center;
      width: 100%;
      min-height: 100%;
      padding: calc(var(--spacing) * 5);
    }
  }

  .modal {
    --ck-modal-out-opacity: 1;
    --ck-modal-out-y: 100%;
    --ck-modal-enter-duration: 0.6s;
    --ck-modal-exit-duration: 0.3s;
    position: absolute;
    bottom: 0;
    left: 0;
    display: flex;
    flex-direction: column;
    width: 100%;
    max-height: 92%;
    border-radius: var(--radius-xl) var(--radius-xl) 0 0;
    background: var(--ck-palette-surface-elevated-primary);
    color: var(--ck-palette-ink);
    font-size: 14px;
    line-height: 1.5;
  }

  .modal:focus {
    outline: none;
  }

  [data-backdrop="fade"] .modal {
    box-shadow: var(--ck-dialog-modal-sheet-fade-shadow);
  }

  [data-entering] .modal {
    opacity: var(--ck-modal-out-opacity);
    transform: translateY(var(--ck-modal-out-y));
  }

  [data-entering-active] .modal,
  [data-entering][data-interrupted] .modal {
    opacity: 1;
    transition-duration: var(--ck-modal-enter-duration);
    transition-property: opacity, transform;
    transition-timing-function: var(--ck-curve-enter);
    transform: translateY(0);
  }

  [data-exiting] .modal {
    opacity: 1;
    transform: translateY(0);
  }

  [data-exiting-active] .modal,
  [data-exiting][data-interrupted] .modal {
    opacity: var(--ck-modal-out-opacity);
    transform: translateY(var(--ck-modal-out-y));
    transition-duration: var(--ck-modal-exit-duration);
    transition-property: opacity, transform;
    transition-timing-function: var(--ck-curve-exit);
  }

  @media (width >= 48rem) {
    .modal {
      --ck-modal-out-opacity: 0;
      --ck-modal-out-y: 20px;
      position: static;
      max-width: var(--ck-modal-max-width, 450px);
      max-height: inherit;
      border-radius: var(--radius-xl);
      box-shadow:
        0 10px 15px -3px
          light-dark(
            color-mix(in srgb, var(--ck-shadow-color) 10%, transparent),
            color-mix(in srgb, var(--ck-shadow-color) 20%, transparent)
          ),
        0 4px 6px -4px
          light-dark(
            color-mix(in srgb, var(--ck-shadow-color) 10%, transparent),
            color-mix(in srgb, var(--ck-shadow-color) 20%, transparent)
          );
    }

    [data-backdrop="fade"] .modal {
      box-shadow: var(--ck-dialog-modal-fade-shadow);
    }

    [data-ck-modal-scroll="inside"] .modal {
      max-height: calc(95vh - 40px);
      overflow: hidden;
    }

    .modal[data-animate="shake"] {
      animation: 0.4s modalShake;
    }
  }

  @keyframes modalShake {
    0% {
      transform: translate(0);
    }

    20%,
    60% {
      transform: translate(-5px);
    }

    40%,
    80% {
      transform: translate(5px);
    }

    to {
      transform: translate(0);
    }
  }

  .modalForm {
    display: flex;
    flex-direction: column;
    width: 100%;
    min-height: 0;
  }

  @media (width >= 48rem) {
    [data-ck-modal-scroll="inside"] .modalForm {
      max-height: calc(95vh - 40px);
      overflow: hidden;
    }
  }

  .modalBody {
    padding: 16px 20px;
  }

  [data-ck-modal-scroll="inside"] .modalBody {
    -webkit-overflow-scrolling: touch;
    border-bottom: 1px solid transparent;
    flex: 1;
    overflow: auto;
  }

  [data-ck-modal-scroll="inside"] .modalBody[data-scrollable="true"] {
    border-bottom-color: var(--border);
    transition: border-color 0.3s;
  }

  .modalHeader {
    display: flex;
    flex-shrink: 0;
    justify-content: space-between;
    align-items: center;
    gap: 8px;
    height: 50px;
    padding: 0 20px;
    border-bottom: 1px solid var(--border);
  }

  .modalHeader .modalTitle {
    margin: 0;
  }

  .modalFooter {
    display: flex;
    flex-shrink: 0;
    justify-content: flex-end;
    align-items: center;
    gap: 8px;
    padding: 16px 20px;
  }

  .modalTitle {
    font-size: 18px;
    font-weight: var(--font-weight-semibold);
    letter-spacing: normal;
    margin: 0 0 8px;
    padding: 0;
    line-height: 1.4;
  }

  .modalDescription {
    color: var(--ck-palette-ink-secondary);
    margin: 0;
    padding: 0;
    font-size: 14px;
  }

  .modalDescription[data-ck-visually-hidden] {
    clip: rect(0, 0, 0, 0);
    white-space: nowrap;
    border: 0;
    width: 1px;
    height: 1px;
    margin: -1px;
    padding: 0;
    overflow: hidden;
  }

  /* ------------------------------------------------------------ scroll fade */

  .scrollFadeMask {
    --ck-edge-mask-top: 0px;
    --ck-edge-mask-bottom: 0px;
    mask-image: linear-gradient(
      to bottom,
      transparent,
      black var(--ck-edge-mask-top) calc(100% - var(--ck-edge-mask-bottom)),
      transparent
    );
  }

  .scrollFadeRoot[data-ck-can-scroll-up="true"] > .scrollFadeMask {
    --ck-edge-mask-top: calc(var(--spacing) * 5);
  }

  .scrollFadeRoot[data-ck-can-scroll-down="true"] > .scrollFadeMask {
    --ck-edge-mask-bottom: calc(var(--spacing) * 10);
  }

  /* ------------------------------------------------------------ close/debug */

  /* bg-media-foreground/20 text-media-foreground hover:bg-media-foreground/30; --color-media-foreground is --white */
  .closeMediaOverlay {
    background-color: color-mix(
      in oklab,
      var(--ck-fixed-white) 20%,
      transparent
    );
    color: var(--ck-fixed-white);
  }

  .closeMediaOverlay:hover {
    background-color: color-mix(
      in oklab,
      var(--ck-fixed-white) 30%,
      transparent
    );
  }

  /* The debug layout outline: --color-chart-blue is the accent blue. */
  .debugOutline {
    position: relative;
    border-radius: var(--radius-lg);
    border: 1px solid
      color-mix(in oklab, var(--ck-palette-accent-blue) 40%, transparent);
  }

  .debugLabel {
    position: absolute;
    top: -0.5rem;
    left: 0.5rem;
    border-radius: 0.25rem;
    padding: 0.125rem 0.375rem;
    background-color: color-mix(
      in oklab,
      var(--ck-palette-accent-blue) 15%,
      transparent
    );
    color: var(--ck-palette-accent-blue);
    font-size: var(--text-xs);
    font-weight: 600;
    letter-spacing: 0.025em;
    text-transform: uppercase;
  }
}

