  | "beacon"
  | "beaconModal"
  | "catalog"
  | "centeredText"
  | "sectioned"
  | "sectionedConfirmation"
  | "confirmation"
  | "creditCheckout"
  | "default"
  | "detailPanel"
  | "expressiveBeacon"
