  return (
    <div
      className={cn(
        "flex w-full flex-col",
        styles.section,
        spacing === "large" && styles.largeSection,
        debug && DEBUG_OUTLINE,
        className
      )}
    >
      {debug ? <DebugLabel name="DialogSection" /> : null}
      {children}
    </div>
  );
};

/** Controls side by side. */
const DialogFormRow = ({
